"""Deterministic build order for a dependency graph. See task.md."""

from __future__ import annotations

import heapq
from collections import deque


class CycleError(ValueError):
    """Raised when the graph contains a cycle.

    `.cycle` names the members of the reported cycle, in depends-on order,
    without repeating the first member at the end.
    """

    def __init__(self, cycle: list[str]) -> None:
        super().__init__("dependency cycle: " + " -> ".join(cycle))
        self.cycle = list(cycle)


def resolve(graph: dict[str, list[str]]) -> list[str]:
    """Return the build order of `graph`, dependencies first."""
    deps: dict[str, set[str]] = {}
    for node, dlist in graph.items():
        deps.setdefault(node, set())
        for d in dlist:
            deps[node].add(d)
            deps.setdefault(d, set())

    all_nodes = set(deps.keys())

    dependents: dict[str, list[str]] = {n: [] for n in all_nodes}
    for n, ds in deps.items():
        for d in ds:
            dependents[d].append(n)

    remaining_deps = {n: set(ds) for n, ds in deps.items()}

    heap = sorted(n for n in all_nodes if not remaining_deps[n])
    heapq.heapify(heap)
    result: list[str] = []
    emitted: set[str] = set()

    while heap:
        node = heapq.heappop(heap)
        if node in emitted:
            continue
        emitted.add(node)
        result.append(node)
        for dependent in dependents[node]:
            remaining_deps[dependent].discard(node)
            if not remaining_deps[dependent] and dependent not in emitted:
                heapq.heappush(heap, dependent)

    if len(result) == len(all_nodes):
        return result

    leftover = all_nodes - emitted
    cycle = _find_reported_cycle(leftover, deps)
    raise CycleError(cycle)


def _bfs_distances(start: str, adj: dict[str, list[str]]) -> dict[str, int]:
    dist = {start: 0}
    queue = deque([start])
    while queue:
        cur = queue.popleft()
        for nxt in adj[cur]:
            if nxt not in dist:
                dist[nxt] = dist[cur] + 1
                queue.append(nxt)
    return dist


def _find_reported_cycle(leftover: set[str], deps: dict[str, set[str]]) -> list[str]:
    adj = {n: sorted(d for d in deps[n] if d in leftover) for n in leftover}
    dist = {n: _bfs_distances(n, adj) for n in leftover}

    shortest_len = None
    for u in leftover:
        for v in adj[u]:
            d = dist[v].get(u)
            if d is not None:
                candidate = d + 1
                if shortest_len is None or candidate < shortest_len:
                    shortest_len = candidate

    for start in sorted(leftover):
        cycle = _smallest_cycle_from(start, shortest_len, adj, dist)
        if cycle is not None:
            return cycle

    raise AssertionError("unreachable: leftover nodes must contain a cycle")


def _smallest_cycle_from(
    start: str,
    length: int,
    adj: dict[str, list[str]],
    dist: dict[str, dict[str, int]],
) -> list[str] | None:
    path = [start]
    visited = {start}

    def dfs(cur: str, steps_left: int) -> list[str] | None:
        if steps_left == 1:
            if start in adj[cur]:
                return list(path)
            return None
        for nxt in adj[cur]:
            if nxt == start or nxt in visited:
                continue
            d = dist[nxt].get(start)
            if d is None or d > steps_left - 1:
                continue
            visited.add(nxt)
            path.append(nxt)
            found = dfs(nxt, steps_left - 1)
            if found is not None:
                return found
            path.pop()
            visited.discard(nxt)
        return None

    return dfs(start, length)
